export const ExportGoodwillReportBody = zod.object({
  "kind": zod.enum(['summary', 'evidence', 'rejections']),
  "query": zod.object({
  "metricId": zod.enum(['net_item_sales', 'source_net', 'shipping_expense', 'daily_customers', 'listings', 'backlog']),
  "sourceId": zod.string().describe('Exactly one source or platform; all-source additive aggregation is forbidden'),
  "period": zod.object({
  "startDate": zod.string().regex(exportGoodwillReportBodyQueryPeriodStartDateRegExp),
  "endDate": zod.string().regex(exportGoodwillReportBodyQueryPeriodEndDateRegExp)
}),
  "storeId": zod.string().optional().describe('Omit for all stores; __unknown__ explicitly selects unresolved attribution'),
  "snapshotAt": zod.coerce.date().optional(),
  "groupBy": zod.enum(['day', 'store', 'category', 'none'])
}).optional(),
  "publicationId": zod.string().optional().describe('Required with query for summary\/evidence; server rejects missing or stale\/mismatched revisions'),
  "batchId": zod.string().optional().describe('Required only for rejections')
})

export const exportGoodwillReportResponseChecksumRegExp = new RegExp('^[a-f0-9]{64}$');


export const ExportGoodwillReportResponse = zod.object({
  "filename": zod.string(),
  "contentType": zod.enum(['text/csv']),
  "csv": zod.string(),
  "checksum": zod.string().regex(exportGoodwillReportResponseChecksumRegExp),
  "synthetic": zod.literal(true),
  "publicationId": zod.string().nullable()
})


